uint8_t scene_race_tilemap_a_ready(const GameState *g);
void set_scene_race_tilemap_a_ready(GameState *g, uint8_t v);

/* Nonzero when the race's tilemap buffer at $0C00 is ready for VRAM $4400; cleared when it is
 * sent */
uint8_t scene_race_tilemap_b_ready(const GameState *g);
void set_scene_race_tilemap_b_ready(GameState *g, uint8_t v);

/* X of the center of the circle $C3:0077 draws into a per-line window table: an 8-bit value in a
 * 16-bit cell, whose high byte the routine clears so it can do its arithmetic on the pair */
uint16_t scene_circle_center_x(const GameState *g);
void set_scene_circle_center_x(GameState *g, uint16_t v);

/* Line of the circle's center: an 8-bit value in a 16-bit cell, whose high byte the routine
 * clears */
uint16_t scene_circle_center_y(const GameState *g);
void set_scene_circle_center_y(GameState *g, uint16_t v);

/* The circle's radius in lines: an 8-bit value in a 16-bit cell, whose high byte the routine
 * clears; 0 closes every line */
uint16_t scene_circle_radius(const GameState *g);
void set_scene_circle_radius(GameState *g, uint16_t v);

/* Address of the circle's per-line table (224 lines of left and right X) */
uint16_t scene_circle_table(const GameState *g);
void set_scene_circle_table(GameState *g, uint16_t v);

/* Bit 0: the circle's table is in bank $7F rather than $7E */
uint8_t scene_circle_table_bank(const GameState *g);
void set_scene_circle_table_bank(GameState *g, uint8_t v);

/* Scene mode bits: bit 7 = interrupts stay enabled through the NMI work (IRQs in use) and the
 * shorter work RAM clear (the title coming back); bit 5 = don't send song changes */
uint8_t scene_flags(const GameState *g);
void set_scene_flags(GameState *g, uint8_t v);

/* Nonzero while a song is being sent to the sound driver; the race skips its sound parameter
 * meanwhile */
uint8_t scene_song_sending(const GameState *g);
void set_scene_song_sending(GameState *g, uint8_t v);

/* The song last sent to the sound driver */
uint8_t scene_song_playing(const GameState *g);
void set_scene_song_playing(GameState *g, uint8_t v);

/* The song the scene wants; the NMI sends it (driver command $10) when it differs from the one
 * playing */
uint8_t scene_song(const GameState *g);
void set_scene_song(GameState *g, uint8_t v);

/* Per-line effect (HDMA) channels to enable, restored after the NMI work */
uint8_t scene_line_effects(const GameState *g);
void set_scene_line_effects(GameState *g, uint8_t v);

/* Display brightness the NMI work restores (0 = forced blank), halved while paused */
uint8_t scene_brightness(const GameState *g);
void set_scene_brightness(GameState *g, uint8_t v);

/* Nonzero while Start may pause the scene */
uint16_t scene_pause_enabled(const GameState *g);
void set_scene_pause_enabled(GameState *g, uint16_t v);

/* 1 while the scene is paused: the task lists don't run and the screen is at half brightness */
uint16_t scene_paused(const GameState *g);
void set_scene_paused(GameState *g, uint16_t v);

/* Set when Start toggles pause and cleared when it is released, so a held Start toggles once */
uint16_t scene_start_held(const GameState *g);
void set_scene_start_held(GameState *g, uint16_t v);

/* Nonzero keeps L+R+Select+Start from resetting the console during a scene */
uint8_t scene_reset_disabled(const GameState *g);
void set_scene_reset_disabled(GameState *g, uint8_t v);

/* Scratch of the circle $C3:0077 draws: whatever it is counting or has just computed -- the
 * octant's x, then y, then the lines left to mirror, then the byte count of a run of closed
 * lines */
uint16_t scene_circle_count(const GameState *g);
void set_scene_circle_count(GameState *g, uint16_t v);

/* Scratch of the circle: the midpoint algorithm's decision value while the outline is stepped,
 * then the mode while the lower half is filled */
uint16_t scene_circle_decision(const GameState *g);
void set_scene_circle_decision(GameState *g, uint16_t v);

/* Scratch of the circle: the table address of the line y above the center, stepped up two bytes
 * a time */
uint16_t scene_circle_row(const GameState *g);
void set_scene_circle_row(GameState *g, uint16_t v);

/* Scratch of the circle: half the table address of the center line, which halves the subtraction
 * that finds the line x above it */
uint16_t scene_circle_center_row_half(const GameState *g);
void set_scene_circle_center_row_half(GameState *g, uint16_t v);

/* The jump's opcode, which installing a handler writes */
