void set_scene_race_line_tables_byte(GameState *g, unsigned at, uint8_t v);

/* The bitmap scaler's output buffer in the race (planar tile graphics), cleared at setup [1792
 * bytes, one at a time] */
enum { SCENE_RACE_SCALER_OUTPUT_BYTES = 1792 };
